$EnvPath = if (Test-Path ".\.env.local") { ".\.env.local" } else { ".\.env" }; $SecretKey = ""; foreach ($Line in Get-Content $EnvPath -ErrorAction SilentlyContinue) { if ($Line -match "^PAYSTACK_SECRET_KEY=(.*)") { $SecretKey = $Matches[1].Trim().Trim("""").Trim('') } }; if (-not $SecretKey) { $SecretKey = "dummy_fallback_secret_key" }; $PayloadStr = '{"event":"transfer.failed","data":{"amount":7500,"reference":"SKB-MASTER-007"}}'; $HmacObj = [System.Security.Cryptography.HMACSHA512]::new([System.Text.Encoding]::UTF8.GetBytes($SecretKey)); $HashHex = $HmacObj.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($PayloadStr)); $SigHex = [System.BitConverter]::ToString($HashHex).Replace("-", "").ToLower(); $HeadersMap = @{ "Content-Type" = "application/json"; "x-paystack-signature" = $SigHex }; Write-Host "" -ForegroundColor Cyan; Write-Host "?? Commencing matrix routing probe pipeline..." -ForegroundColor Cyan; $Endpoints = @("http://localhost:3001/api/webhooks/paystack", "http://localhost:3001/api/paystack-webhook"); foreach ($Url in $Endpoints) { try { Write-Host "Testing POST request to $Url..." -ForegroundColor Yellow; $Response = Invoke-RestMethod -Uri $Url -Method Post -Body $PayloadStr -Headers $HeadersMap -TimeoutSec 5; Write-Host "? Path Success: Response received from $Url." -ForegroundColor Green; $Response | ConvertTo-Json | Write-Host } catch { Write-Host "? Matrix Response: [$Url] -> status: $($_.Exception.Message)" -ForegroundColor Red; if ($_.Response) { $StreamReader = [System.IO.StreamReader]::new($_.Response.GetResponseStream()); Write-Host "?? Server Response Payload: $($StreamReader.ReadToEnd())" -ForegroundColor DarkRed } } }
